/**
 * Renames the Android photo cropper's confirm button from "CROP" to "SAVE".
 *
 * expo-image-picker's `allowsEditing` opens com.vanniktech:android-image-cropper,
 * whose only confirm action is the string `crop_image_menu_crop` ("Crop").
 * Testers read that as "there is no Save button" on the profile and team photo
 * screens, where tapping it is exactly what saves the photo. An app-level
 * string with the same name overrides the library's at build time.
 *
 * A plugin rather than an edit under android/: that folder is regenerated by
 * `expo prebuild` (and by EAS Build), which would silently drop the change.
 */
const { withStringsXml, AndroidConfig } = require('expo/config-plugins');

module.exports = function withCropSaveLabel(config) {
  return withStringsXml(config, (cfg) => {
    cfg.modResults = AndroidConfig.Strings.setStringItem(
      [AndroidConfig.Resources.buildResourceItem({ name: 'crop_image_menu_crop', value: 'Save' })],
      cfg.modResults,
    );
    return cfg;
  });
};
